# each tool is handed a credential scoped to its purpose
def get_order(order_id: str) -> dict:
    creds = mint_token(scopes=["orders:read"], ttl_minutes=15)
    return orders_api(creds).fetch(order_id)      # cannot write

def issue_refund(order_id: str, amount: float) -> dict:
    # write scope limited to refunds, capped amount, needs approval
    assert amount <= MAX_AUTO_REFUND, "exceeds auto-approval limit"
    creds = mint_token(scopes=["refunds:write"], ttl_minutes=5)
    return refunds_api(creds).create(order_id, amount)
# a hijacked get_order can never issue a refund

