# BEFORE: god-tool -- ambiguous args, one over-broad entry point
def manage_order(action, order_id=None, amount=None, reason=None):
    if action == "get":
        return {"order_id": order_id, "status": "shipped"}
    elif action == "refund":
        return {"order_id": order_id, "refunded": amount}
    elif action == "cancel":
        return {"order_id": order_id, "cancelled": True, "reason": reason}
    raise ValueError(f"unknown action {action}")

# AFTER: three composable, single-purpose tools
def get_order(order_id: str) -> dict:
    return {"order_id": order_id, "status": "shipped"}

def refund_order(order_id: str, amount: float) -> dict:
    return {"order_id": order_id, "refunded": amount}

def cancel_order(order_id: str, reason: str) -> dict:
    return {"order_id": order_id, "cancelled": True, "reason": reason}

# the model composes exactly what it needs, one clear call at a time
print(get_order("O-42"))
print(refund_order("O-42", 19.99))

MAX_AUTO_REFUND = 50.0

class Scope:
    def __init__(self, scopes):
        self.scopes = set(scopes)
    def require(self, needed):
        if needed not in self.scopes:
            raise PermissionError(f"missing scope: {needed}")

def get_order(order_id: str, scope: Scope) -> dict:
    scope.require("orders:read")            # read-only
    return {"order_id": order_id, "total": 42.0}

def issue_refund(order_id: str, amount: float, scope: Scope) -> dict:
    scope.require("refunds:write")          # write, narrowly scoped
    if amount > MAX_AUTO_REFUND:            # cap the blast radius
        return {"status": "needs_approval", "amount": amount}
    return {"status": "refunded", "amount": amount}

read_scope = Scope(["orders:read"])         # given to a lookup tool
print(get_order("O-1", read_scope))

# a hijacked read tool trying to refund is blocked by its scope
try:
    issue_refund("O-1", 10.0, read_scope)
except PermissionError as e:
    print("blocked:", e)

refund_scope = Scope(["refunds:write"])
print(issue_refund("O-1", 999.0, refund_scope))  # over cap -> approval
